CREATE TABLE platform_imports(id INTEGER PRIMARY KEY,hash TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE platform_changes(id INTEGER PRIMARY KEY,batch_id INTEGER REFERENCES platform_imports(id),entity TEXT NOT NULL,row_id INTEGER NOT NULL,after_json TEXT NOT NULL,undone INTEGER NOT NULL DEFAULT 0);
CREATE TABLE platform_audit(id INTEGER PRIMARY KEY,action TEXT NOT NULL,detail TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE platform_peers(id TEXT PRIMARY KEY,name TEXT NOT NULL,public_key TEXT NOT NULL,revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE platform_sync_map(peer TEXT NOT NULL,remote_id TEXT NOT NULL,local_id INTEGER,base_json TEXT,PRIMARY KEY(peer,remote_id));
CREATE TABLE platform_sync_packets(hash TEXT PRIMARY KEY,received_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE platform_publishers(public_key TEXT PRIMARY KEY,name TEXT NOT NULL);
CREATE TABLE platform_plugins(name TEXT PRIMARY KEY,sha256 TEXT NOT NULL,publisher TEXT NOT NULL,installed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
